def shortest(N: int, edgeList: list[list[int]]) -> int:
    # Initialize distance array with infinity
    dist = [float('inf')] * N
    dist[0] = 0

    # Since edges only go from lower to higher vertices, we can process in topological order
    # which is simply 0, 1, ..., N-1 due to start < end constraint
    for u in range(N):
        if dist[u] == float('inf'):
            continue  # no path to u
        for edge in edgeList:
            if edge[0] == u:
                v, w = edge[1], edge[2]
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    return dist[N-1] if dist[N-1] != float('inf') else -1
